html:
{% set die = namespace(data={}) %}
{% set columns = [] %}
{% set repair_column = [] %}

{# Dynamic Columns #}
{% for df in frappe.get_meta("Traveler Item Table").fields %}
    {% if df.in_list_view
        and not df.hidden
        and df.fieldname != "delivery_date"
        and "die_no" not in df.fieldname
        and "die_des" not in df.fieldname
        and "rate" not in df.fieldname
        and "amount" not in df.fieldname
        and "image" not in df.fieldname
        and "additional_description" not in df.fieldname
    %}
        {% if df.fieldname in ["qty", "quantity"] %}
            {% set _ = columns.insert(0, df) %}
        {% else %}
            {% set _ = columns.append(df) %}
        {% endif %}
    {% endif %}
{% endfor %}

{# Repair Columns: Enforce QTY then ACCEPTED_QTY first #}
{% set repair_field_order = ["qty", "quantity", "accepted_qty"] %}
{% for target_fn in repair_field_order %}
    {% for df in frappe.get_meta("Repairs Traveler Item").fields %}
        {% if df.fieldname == target_fn and df not in repair_column %}
            {% set _ = repair_column.append(df) %}
        {% endif %}
    {% endfor %}
{% endfor %}

{# Repair Columns (Remaining fields) #}
{% for df in frappe.get_meta("Repairs Traveler Item").fields %}
    {% if df.in_list_view
        and not df.hidden
        and df.fieldname not in ["qty", "quantity", "accepted_qty"]
        and "die_no" not in df.fieldname
        and "die_des" not in df.fieldname
        and "rate" not in df.fieldname
        and "amount" not in df.fieldname
        and "image" not in df.fieldname
    %}
        {% set _ = repair_column.append(df) %}
    {% endif %}
{% endfor %}

{# Prepare Die Data #}
{% if doc.get("item") %}
    {% for item in doc.item %}
        {% set dies = [] %}
        {% for i in range(1, 5) %}
            {% set code = item.get("die_no" ~ i) %}
            {% set desc = item.get("die_des" ~ i) %}
            {% if code or desc %}
                {% set _ = dies.append({"die_code": code}) %}
            {% endif %}
        {% endfor %}

        {% set item_key = item.item_code or loop.index %}
        {% set _ = die.data.update({
            item_key: {
                "row": item,
                "custom_description": item.get("custom_description") or item.get("additional_description"),
                "description": item.get("description") or "",
                "die_no_description": item.get("die_no_description") or "",
                "dies": dies
            }
        }) %}
    {% endfor %}
{% endif %}

<div style="font-family: Arial, sans-serif; font-size:10px; line-height:1.2; color:black;">

<div id="header-html" class="visible-pdf">
    <table style="width: 100%; border-collapse: collapse; font-family: Arial, Helvetica, sans-serif; margin-top:-50px;">

        <!-- ROW 2: LOGO AND ADDRESS -->
        <tr>
            <!-- LEFT: Logo -->
            <td style="width: 33.33%; vertical-align: top; text-align: left; padding: 0;">
                {% set company_logo = frappe.db.get_value("Company", doc.company, "company_logo") %}
                
                {% if company_logo %}
                    <div style="height: 84px; overflow: hidden; position: relative; width: 100%;">
                        <img src="{{ company_logo }}" alt="{{ doc.company }}"
                             style="position: absolute; top: -18px; left: 0; height: 120px; width: auto;">
                    </div>
                {% endif %}
            </td>
            
            <td  style="width: 33.33%; text-align: center; font-size: 25px; font-weight: 400; color: #222; padding-bottom: 15px;">
                Repair Traveler Order
            </td>
            <!-- RIGHT: Address -->
            <td style="width: 33.33%; vertical-align: top; text-align: right; font-size: 12px; line-height: 1.4; padding: 0;">
                
                {% set company_address = frappe.db.get_value(
                    "Address",
                    doc.company_address,
                    ["address_line1", "city", "state", "pincode"],
                    as_dict=True
                ) %}

                {% if company_address %}
                    {{ company_address.address_line1 or "" }},<br>
                    {{ company_address.city or "" }},
                    {{ company_address.state or "" }},
                    {{ company_address.pincode or "" }}<br>
                {% endif %}

                {% set company_details = frappe.db.get_value(
                    "Company",
                    doc.company,
                    ["website", "phone_no", "fax"],
                    as_dict=True
                ) %}
                TEL: {{ company_details.phone_no or "" }},<br>
                FAX: {{ company_details.fax or "" }}<br>
                
                {{ company_details.website or "" }}
            </td>
        </tr>
    </table>
    <div style="border-top: 2px solid #222; margin-top: 2px; padding: 0;"></div>
    <div style="border-top: 3px solid #222; margin: 4px 0 0 0; padding: 0;"></div>
</div>

{# Header Table #}
<table style="width:100%; border-collapse: collapse; margin-top:8px; font-size:10px;">
    <tr style="background:#d9d9d9;">
        <td style="border:1px solid #000; padding:6px; width:33%;">
            <b>Traveler/Sales#:</b>
            {{ doc.order_status or "" }}
        </td>
        <td style="border:1px solid #000; padding:6px; width:33%;">
            <b>Order Date:</b>
            {% if doc.transaction_date %}
                {{ frappe.utils.formatdate(doc.transaction_date, "dd MMM yyyy") }}
            {% endif %}
        </td>
        <td style="border:1px solid #000; padding:6px; width:34%;">
            <b>Ship Via:</b>
            {{ doc.shipping_rule or "NA" }}
        </td>
    </tr>
</table>

{# Customer Table #}
<table style="width:100%; border-collapse: collapse; font-size:10px;">
    <tr>
        <td style="border:1px solid #000; padding:8px;">
            <b>SHIP TO</b><br>
            {{ doc.customer_name or "" }}<br>
            {{ doc.shipping_address or "" }}
        </td>
    </tr>
</table>

{% if doc.get("is_repair_") and doc.get("repair_item_table") %}
<table style="width:100%; border-collapse: collapse; margin-top:10px; font-size:10px;">
    <thead>
        <tr style="background:#d9d9d9; color:black">
            {% for col in repair_column %}
                <th style="border:1px solid #000; padding:6px; color:black; font-size:10px;">
                    <strong>
                        {% if col.fieldname == "item_code" %}
                            SERVICE
                        {% elif col.fieldname in ["qty", "quantity"] %}
                            QTY
                        {% elif col.fieldname == "accepted_qty" %}
                            ACCEPTED QTY
                        {% else %}
                            {{ (col.label or "").upper() }}
                        {% endif %}
                    </strong>
                </th>
            {% endfor %}
        </tr>
    </thead>
    <tbody>

    {% for row in doc.repair_item_table %}
        <tr>
            {% for col in repair_column %}
                <td style="border:1px solid #000; padding:6px; font-size:10px;">
                    {% if col.fieldtype == "Date" and row.get(col.fieldname) %}
                        {{ frappe.utils.formatdate(row.get(col.fieldname), "dd MMM yyyy") }}
                    {% else %}
                        {{ row.get(col.fieldname) or "" }}
                    {% endif %}
                </td>
            {% endfor %}
        </tr>
    {% endfor %}

    </tbody>
</table>
{% endif %}

{# Main Table #}
<table style="width:100%; border-collapse: collapse; margin-top:10px; font-size:10px;">
    <thead>
        <tr style="background:#d9d9d9; color:black">
            {% for col in columns %}
                <th style="border:1px solid #000; padding:6px; color:black; font-size:10px;">
                    <strong>
                        {% if col.fieldname in ["qty", "quantity"] %}
                            QTY
                        {% else %}
                            {{ (col.label or "").upper() }}
                        {% endif %}
                    </strong>
                </th>
            {% endfor %}

            <th style="border:1px solid #000; padding:6px; width:10%; color:black; font-size:10px;">
                <strong>DIE NO</strong>
            </th>

            <th style="border:1px solid #000; padding:6px; width:20%; color:black; font-size:10px;">
                <strong>DESCRIPTION</strong>
            </th>

            <th style="border:1px solid #000; padding:6px; width:20%; color:black; font-size:10px;">
                <strong>NOTES</strong>
            </th>
        </tr>
    </thead>

    <tbody>

    {% for code, data in die.data.items() %}
        {% set row = data.row %}
        {% set die_list = data.dies %}
        {% set row_count = die_list|length if (die_list is defined and die_list) else 1 %}
        {% set render_dies = die_list if (die_list is defined and die_list) else [{}] %}

        {% for d in render_dies %}
        <tr>

            {% if loop.first %}
                {% for col in columns %}
                    <td rowspan="{{ row_count }}"
                        style="border:1px solid #000; padding:6px; font-size:10px; vertical-align:middle;">
                        {% if col.fieldtype == "Date" and row.get(col.fieldname) %}
                            {{ frappe.utils.formatdate(row.get(col.fieldname), "dd MMM yyyy") }}
                        {% else %}
                            {{ row.get(col.fieldname) or "" }}
                        {% endif %}
                    </td>
                {% endfor %}
            {% endif %}

            <td style="border:1px solid #000; padding:6px; font-size:10px;">

            {% if d.die_code %}
                {{ d.die_code }}
            {% else %}
                {{ data.description or data.die_no_description or "" }}
            {% endif %}
        
            </td>
                    {% if loop.first %}
        <td rowspan="{{ row_count }}"
            style="border:1px solid #000; padding:6px; font-size:10px; vertical-align:middle;">
            {{ data.custom_description or data.description or "" }}
        </td>
        {% endif %}

            <!-- NOTES -->
            {% if loop.first %}
                <td rowspan="{{ row_count }}"
                    style="border:1px solid #000; padding:6px; font-size:10px; vertical-align:middle;">
                    {{ row.get("notes") or "" }}
                </td>
            {% endif %}

        </tr>
        {% endfor %}
    {% endfor %}

    </tbody>
</table>

</div>
